21	/*
22	 * This is an AST-based query fuzzer that makes random modifications to query
23	 * AST, changing numbers, list of columns, functions, etc. It remembers part of
24	 * queries it fuzzed previously, and can substitute these parts to new fuzzed
25	 * queries, so you want to feed it a lot of queries to get some interesting mix
26	 * of them. Normally we feed SQL regression tests to it.
27	 */
28	struct QueryFuzzer
29	{
30	    pcg64 fuzz_rand{randomSeed()};
31	
32	    // We add elements to expression lists with fixed probability. Some elements
33	    // are so large, that the expected number of elements we add to them is
34	    // one or higher, hence this process might never finish. Put some limit on the
35	    // total depth of AST to prevent this.
36	    // This field is reset for each fuzzMain() call.
37	    size_t current_ast_depth = 0;
38	
39	    // These arrays hold parts of queries that we can substitute into the query
40	    // we are currently fuzzing. We add some part from each new query we are asked
41	    // to fuzz, and keep this state between queries, so the fuzzing output becomes
42	    // more interesting over time, as the queries mix.
43	    std::unordered_set<std::string> aliases_set;
44	    std::vector<std::string> aliases;
45	
46	    std::unordered_map<std::string, ASTPtr> column_like_map;
47	    std::vector<ASTPtr> column_like;
48	
49	    std::unordered_map<std::string, ASTPtr> table_like_map;
50	    std::vector<ASTPtr> table_like;
51	
52	    // Some debug fields for detecting problematic ASTs with loops.
53	    // These are reset for each fuzzMain call.
54	    std::unordered_set<const IAST *> debug_visited_nodes;
55	    ASTPtr * debug_top_ast = nullptr;
56	
57	
58	    // This is the only function you have to call -- it will modify the passed
59	    // ASTPtr to point to new AST with some random changes.
60	    void fuzzMain(ASTPtr & ast);
61	
62	    // Various helper functions follow, normally you shouldn't have to call them.
63	    Field getRandomField(int type);
64	    Field fuzzField(Field field);
65	    ASTPtr getRandomColumnLike();
66	    void replaceWithColumnLike(ASTPtr & ast);
67	    void replaceWithTableLike(ASTPtr & ast);
68	    void fuzzOrderByElement(ASTOrderByElement * elem);
69	    void fuzzOrderByList(IAST * ast);
70	    void fuzzColumnLikeExpressionList(IAST * ast);
71	    void fuzzWindowFrame(ASTWindowDefinition & def);
72	    void fuzz(ASTs & asts);
73	    void fuzz(ASTPtr & ast);
74	    void collectFuzzInfoMain(ASTPtr ast);
75	    void addTableLike(ASTPtr ast);
76	    void addColumnLike(ASTPtr ast);
77	    void collectFuzzInfoRecurse(ASTPtr ast);
78	};
